/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CompanyNAFCode.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, CompanyNAFCode))]
internal class GUPPricingAttributeCustTableCompanyNAFCode extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CompanyNAFCode);
}

public str getRefValue(Str _defaultValue)
{
    CompanyNAFCode companyNAFCode;
    str ret = '';
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(CompanyNAFCode)).addRange(fieldNum(CompanyNAFCode, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        companyNAFCode = qr.get(tableNum(CompanyNAFCode), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ',';
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += companyNAFCode.CompanyIdNAF;
    }

    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return CompanyNAFCode::find(recId) ? true : false;
}

public void lookupAllowedValues(object _formStringControl)
{
    GUPCompanyNAFCodeLookup companyNAFCodeLookup = new GUPCompanyNAFCodeLookup(true);
    companyNAFCodeLookup.performLookup(_formStringControl);

}
